// 1. Get raw data from the Webhook
const rawData = $json;

// 2. Normalization Constants (Based on the X Education Dataset limits)
// These ensure your numbers are scaled between 0 and 1
const MAX_VISITS = 40;            // Typical max visits in the dataset
const MAX_TIME = 2272;            // Max 'Total Time Spent on Website' in seconds
const MAX_PAGE_VIEWS = 20;        // Max 'Page Views Per Visit'

// 3. One-Hot Encoding Logic for 'Lead Origin'
let origin_api = 0;
let origin_landing = 0;

if (rawData['Lead Origin'] === 'API') {
    origin_api = 1;
} else if (rawData['Lead Origin'] === 'Landing Page Submission') {
    origin_landing = 1;
}

// 4. Mathematical Scaling (Normalization)
// Using Math.min to ensure values never exceed 1.0
const visits_scaled = Math.min(rawData['TotalVisits'] || 0, MAX_VISITS) / MAX_VISITS;
const time_scaled = Math.min(rawData['Total Time Spent on Website'] || 0, MAX_TIME) / MAX_TIME;
const views_scaled = Math.min(rawData['Page Views Per Visit'] || 0, MAX_PAGE_VIEWS) / MAX_PAGE_VIEWS;

// 5. Return the clean feature vector for the ANN
return {
    visits_scaled,
    time_scaled,
    views_scaled,
    origin_api,
    origin_landing
};

// 1. The Trained Weights (W1: 5x4, W2: 4x1)
const W1 = [[0.004596620709605863, -0.008107305890232707, -0.01542705554080637, 0.015056886272161438], [0.0033899127605169, -0.15475254873098726, -0.20270892983812186, 0.0025471451677008903], [-0.006089275647701876, -0.014574659586168525, -0.07581137043076396, -0.004832634732022187], [-0.07694829655708747, -0.01913280244657798, -0.7635756972489905, -0.007760000900711198], [-0.010128311203344238, -0.30573506902271796, -0.9132357705374591, -0.014194275154171003]];
const B1 = [-0.07936791927274617, -0.42396941004248073, -1.6480266308228948, -0.008263743359254908];
const W2 = [[0.0009591913213831803], [0.4149784131879748], [-4.310222200226491], [-0.012271724755471817]];
const B2 = -40.30546827118063;

// 2. Input Vector from the previous node (Pre-Processor)
// Order: [TotalVisits, TimeSpent, PageViews, Origin_API, Origin_Landing]
const inputs = [
  $node["Pre-Processor"].json["visits_scaled"],
  $node["Pre-Processor"].json["time_scaled"],
  $node["Pre-Processor"].json["views_scaled"],
  $node["Pre-Processor"].json["origin_api"],
  $node["Pre-Processor"].json["origin_landing"]
];

// 3. Mathematical Functions
const relu = (x) => Math.max(0, x);
const sigmoid = (x) => 1 / (1 + Math.exp(-x));

// 4. Layer 1: Matrix Multiplication (Input * W1 + B1)
let hiddenLayer = B1.map((b, j) => {
  let sum = b;
  for (let i = 0; i < inputs.length; i++) {
    sum += inputs[i] * W1[i][j];
  }
  return relu(sum);
});

// 5. Layer 2: Matrix Multiplication (Hidden * W2 + B2)
let finalSum = B2;
for (let i = 0; i < hiddenLayer.length; i++) {
  finalSum += hiddenLayer[i] * W2[i][0];
}

const probability = sigmoid(finalSum);

return {
  prediction_score: probability,
  is_hot_lead: probability > 0.5 // Standard threshold
};
